#!/bin/bash
# Block edits to platform-generated files.
# Enforces: Critical rule 1 — never edit declarations/, B.d.ts, scriptlibrary.d.ts, Globals.d.ts.
#
# These files are generated by the platform and replaced on the next `b6p pull`, so a hand edit
# is lost. Until it is, the code type-checks against a declaration the platform will never
# produce, which is worse than a plain compile error.
#
# Also blocks the files b6p 0.9 owns: the build manifest `.b6p-build.json` (the platform checks it
# before it publishes, so a hand edit can publish a stale build or block the publish) and anything
# under `draft/.git/` (draft/ is a git clone; b6p makes the commits).

HOOK_NAME="block-generated-files"
# ${BASH_SOURCE[0]%/*} rather than $(dirname ...): no external command, so this still works
# when PATH is empty. And a failed source is fatal — without the helper the checks below would
# all see an empty value, match nothing, and exit 0, which is the fail-open bug again.
source "${BASH_SOURCE[0]%/*}/lib/hook-input.sh" || {
  echo "BLOCKED: the BlueStep guardrail hook could not load its input helper (${BASH_SOURCE[0]%/*}/lib/hook-input.sh), so it cannot check this call. Reinstall or update the bluestep-tools plugin." >&2
  exit 2
}
hook_require_parse

# file_path / path: Claude Code and Codex. target_file / relative_workspace_path: the names
# Cursor's agent tools have used; its preToolUse docs do not show the Write tool's input, so
# all four are tried (see dist/cursor/bluestep-tools/hooks/README.md, "Not yet proven live").
FILE=$(hook_field_path file_path path target_file relative_workspace_path)

# Both forms: anywhere in an absolute path, and at the start of a workspace-relative one (a
# Cursor workspace opened on the component folder sends "declarations/x.d.ts").
if [[ "$FILE" == *"/declarations/"* ]] \
   || [[ "$FILE" == "declarations/"* ]] \
   || [[ "$FILE" == *"B.d.ts" ]] \
   || [[ "$FILE" == *"scriptlibrary.d.ts" ]] \
   || [[ "$FILE" == *"Globals.d.ts" ]]; then
  echo "BLOCKED: '$FILE' is platform-generated and gets replaced on the next pull, so this edit would be lost. If a declaration is wrong or missing, fix it on the platform — usually by adding the query or form-field import there — then run: b6p pull \"<DAV URL>\"" >&2
  exit 2
fi

# hook_field_path has already turned backslashes into forward slashes.
if [[ "$FILE" == *".b6p-build.json" ]]; then
  echo "BLOCKED: '$FILE' is the build manifest b6p writes on a clean publish build, and the platform checks it before it publishes. Do not edit it by hand: publish again with b6p push --snapshot, which rebuilds and rewrites it." >&2
  exit 2
fi
# Only a component's draft/.git: the project's own .git (its hooks, for one) is not b6p's.
if [[ "$FILE" == *"/draft/.git/"* ]] || [[ "$FILE" == "draft/.git/"* ]]; then
  echo "BLOCKED: '$FILE' is inside draft/.git, the git repository b6p clones for this component. Let b6p pull and b6p push change it; do not edit its files by hand." >&2
  exit 2
fi

exit 0
